'use strict';
const cards=[
 {title:'Ask the right question.',text:'A useful question has a clear purpose: check a fact, find a detail, choose an option or ask politely.\n\nAre we on time? → check\nWhere does the bus stop? → detail\nWould you like tea or coffee? → choice',tip:'At a station, start with the information you actually need.'},
 {title:'Put the helper before the subject.',text:'With be, an auxiliary or a modal: question word + helper + subject + main verb.\n\nWhere are you going?\nHave you booked a seat?\nWhere can I charge my phone?',tip:'The first helper moves. The other verb forms stay together.'},
 {title:'No helper? Add do, does or did.',text:'In present/past simple questions, use do/does/did + subject + BASE verb.\n\nWhere does this train stop?\nWhen did your train leave?\n\nDoes/did carries the tense: stop, not stops; leave, not left.',tip:'With be, do not add do: Is the platform open?'},
 {title:'Who did it? Who did you meet?',text:'Ask about the doer: Who found the ticket? No do/did in an ordinary affirmative subject question.\n\nAsk about the object: Who did Daniel call? Daniel is still the subject.\n\nWho is waiting? keeps is because it builds the continuous tense.',tip:'Emphatic Who DID call? is possible, but it is a special contrast, not the neutral pattern.'},
 {title:'Make the question more polite.',text:'Use Could you tell me…? or Do you know…? Then use STATEMENT order inside.\n\nWhere is the platform?\n→ Could you tell me where the platform is?\n\nRemove do/does/did: when does it leave → when it leaves.',tip:'The opening is a question. The clause inside it is not inverted.'},
 {title:'Yes/no information needs if or whether.',text:'Is the replacement bus free?\n→ Do you know if the replacement bus is free?\n→ Do you know whether the replacement bus is free?\n\nCould you tell me…? ends with ?.\nI wonder… is a statement and ends with a full stop.',tip:'Keep the original tense when a polite frame does not change the time.'},
 {title:'Keep the preposition.',text:'Everyday: Who did you travel WITH?\nWhat are you looking FOR?\n\nFormal: To WHOM should I send this?\n\nHow many + plural countable: How many stops…?\nHow much + uncountable: How much time…?',tip:'Choose the register for the situation. Formal wording is not automatically more useful.'},
 {title:'Check expectations and offer choices.',text:'Didn’t you book a seat? usually suggests I thought you had, or surprise that you did not. It can sound critical.\n\nDo you want a single or a return? offers alternatives.\n\nNow practise questions you could use on a real journey.',tip:'Negative questions often carry an attitude; use a neutral question when you simply need information.'}
];
const tasks=[
 {type:'gap',prompt:'___ the replacement bus stop here? Use the present simple.',answer:'Does',why:'The subject is the replacement bus (it). Use does before the subject and leave stop in its base form.',hint:'Find the subject: the replacement bus = it. This is a present simple question with an ordinary verb, so choose the third-person question helper.'},
 {type:'choice',prompt:'Ask about the departure time yesterday.',answer:'When did the train leave?',options:['When did the train leave?','When did the train left?','When the train left?'],why:'Yesterday requires past simple. Did carries the past tense, so leave stays in the base form.',hint:'The question asks for a time, so begin with When. Yesterday needs a past question helper; the main verb must not carry the past tense again.'},
 {type:'order',prompt:'Build a question about an action happening now.',answer:'Where are the passengers waiting?',why:'Where asks for a place. In a present continuous question, are goes before the subject; waiting stays after it.',hint:'Keep the passengers together as the subject. The continuous tense has two parts; move only its first part before the subject.'},
 {type:'edit',prompt:'Correct the word order: Why you are looking at the map?',answer:'Why are you looking at the map?',why:'A direct question needs Why + are + you + looking. The prepositional phrase at the map remains at the end.',hint:'You already have the correct tense and vocabulary. The problem is the order of the subject you and the helper are.'},
 {type:'choice',prompt:'You do not know which person showed Daniel the bus stop. Ask about the doer in a neutral question.',answer:'Who showed Daniel the bus stop?',options:['Who showed Daniel the bus stop?','Who did Daniel show the bus stop?','Who Daniel showed the bus stop?'],why:'Who replaces the unknown subject. In this neutral affirmative subject question, showed stays past simple without did.',hint:'Imagine the answer: A passenger showed Daniel the bus stop. Replace A passenger, not Daniel. Is there a separate subject left after Who?'},
 {type:'rewrite',prompt:'A passenger found my ticket. Ask about the person. Begin with Who.',answer:'Who found my ticket?',why:'A passenger is the subject. Who replaces it directly; found remains the past simple verb.',hint:'Cross out only A passenger. The rest of the original sentence already follows the unknown doer in the correct order.'},
 {type:'rewrite',prompt:'Daniel called Emma. Ask who Daniel called. Begin with Who.',answer:'Who did Daniel call?|Whom did Daniel call?',why:'Daniel remains the subject; Emma is the object you are asking about. Use did + Daniel + call after Who.',hint:'This time you are replacing Emma, not Daniel. Because Daniel is still the subject, the question needs a past simple helper.'},
 {type:'gap',prompt:'Where ___ I charge my phone? Add a modal meaning “is it possible”.',answer:'can|could',why:'Can I…? asks about possibility or permission. Could I…? is also possible and more tentative. A modal comes before the subject.',hint:'The phone needs power. You want to ask what is possible, not what someone already did. Put a possibility modal directly before I.'},
 {type:'edit',prompt:'Correct one verb form: Have you saw the notification?',answer:'Have you seen the notification?',why:'Present perfect is have + past participle. The participle of see is seen; saw is past simple.',hint:'Have already builds the present perfect. Check which form of see belongs after have: the past simple form or the past participle?'},
 {type:'order',prompt:'Build a polite question about the platform.',answer:'Could you tell me where the platform is?',why:'Could you tell me is the question frame. Inside, use where + the platform + is, with statement order.',hint:'Start with the four-word polite frame. Inside the remaining clause, the platform must come before its verb.'},
 {type:'choice',prompt:'Make “Is the replacement bus free?” indirect.',answer:'Do you know whether the replacement bus is free?',options:['Do you know whether the replacement bus is free?','Do you know whether is the replacement bus free?','Do you know the replacement bus free?'],why:'A yes/no embedded question needs if or whether. After it, keep the subject before is.',hint:'There is no question word in the original. Add a connector meaning whether or not, then use normal statement order.'},
 {type:'rewrite',prompt:'Where does the bus leave from? Begin: Could you tell me…',answer:'Could you tell me where the bus leaves from?',why:'After the polite frame, remove does and give the present simple verb its -s: the bus leaves. Keep from.',hint:'The embedded part should read like a statement: the bus + verb. Removing does means the main verb must now agree with the bus.'},
 {type:'edit',prompt:'Add the missing preposition: Who did you travel?',answer:'Who did you travel with?|With whom did you travel?',why:'Travel with someone is the intended meaning. Everyday questions commonly leave with at the end; With whom…? is formal.',hint:'The answer would be I travelled with a friend. Which small word links travelled to the companion? Keep it in the question.'},
 {type:'gap',prompt:'Formal email: To ___ should I send the report?',answer:'whom',why:'In formal wording, use whom for a person after a preposition placed at the start.',hint:'To is already at the front, so this is the formal pattern. Choose the object form of the question word for a person.'},
 {type:'choice',prompt:'A friend says, “Didn’t you book a seat?” What are they most likely suggesting?',answer:'They expected you to book one and are checking.',options:['They expected you to book one and are checking.','They want to know where the seat is.','They are offering you a choice of seats.'],why:'The negative question checks an expectation and can show surprise. It does not ask for a place or offer alternatives.',hint:'Compare Did you book? with Didn’t you book? The negative version often carries an assumption about what the listener was expected to do.'},
 {type:'order',prompt:'Build a question offering two ticket options.',answer:'Would you like a single or a return?',why:'Would you like…? is a polite offer. Or joins the two alternatives, a single and a return.',hint:'Use the polite offer frame first. The options are two noun phrases joined by or; they are not part of a yes/no answer.'},
 {type:'gap',prompt:'How ___ time do we have before the connection?',answer:'much',why:'Time here is uncountable, so use how much. Use how many with countable plural nouns such as minutes.',hint:'Look at the noun immediately after the gap: time, not minutes. Decide whether that noun is countable in this meaning.'},
 {type:'rewrite',prompt:'Turn this into an ordinary direct question: I wonder why the train was cancelled.',answer:'Why was the train cancelled?',why:'Remove the statement frame I wonder. In the direct passive question, was goes before the subject the train.',hint:'You are moving in the opposite direction now: from an embedded clause back to a direct question. Move the first helper before the subject.'}
];
const listening=[
 {type:'choice',prompt:'What is Daniel’s main message?',answer:'Information helps when you use it calmly.',options:['Information helps when you use it calmly.','A detailed plan prevents every travel problem.','A phone always solves problems automatically.'],why:'His final point is that the phone supplied information, but calm decisions made the difference.',evidence:'It gave me information. The real difference was making one calm decision after another.',hint:'Listen to the final paragraph. Separate what the phone supplied from what Daniel himself had to do.'},
 {type:'choice',prompt:'Why was Daniel travelling to Austria?',answer:'To attend a friend’s wedding.',options:['To attend a friend’s wedding.','To start a new job.','To visit his family.'],why:'The purpose appears in his opening explanation of the journey.',evidence:'I was travelling alone from Prague to a small town in Austria for a friend’s wedding.',hint:'Listen near the beginning for for + an event. The destination and the reason for the trip are different details.'},
 {type:'gap',prompt:'Which platform was mentioned for the replacement bus? Write the number.',answer:'14|fourteen|platform 14',why:'The announcement pointed passengers towards a replacement bus from Platform 14.',evidence:'replacement bus from Platform 14.',hint:'Find the phrase Daniel types into the translation app. The number belongs to the platform, not his battery level.'},
 {type:'choice',prompt:'Why did the other passengers make Daniel feel more confused?',answer:'They appeared unconcerned.',options:['They appeared unconcerned.','They told him the app was wrong.','They all left the carriage immediately.'],why:'Some were sleeping or listening to music. Their calm behaviour did not match his worry; nobody told him the app was wrong.',evidence:'Nobody seemed worried, which made me feel even more confused.',hint:'Listen for the contrast between Daniel’s feelings and the behaviour around him. Do not assume passengers spoke to him.'},
 {type:'choice',prompt:'Which two things did he do to save battery?',answer:'Closed other apps and dimmed the screen.',options:['Closed other apps and dimmed the screen.','Switched off the phone and borrowed a ticket.','Kept the translation app open and increased brightness.'],why:'He kept only the train app running and lowered screen brightness. The transcript does not say he charged the phone.',evidence:'I turned off everything except the train app and lowered the screen brightness.',hint:'Listen after twelve percent. Identify two actions he actually took; ignore sensible travel advice that the story never mentions.'},
 {type:'gap',prompt:'How many minutes later was the new arrival time? Write the number.',answer:'25|twenty-five|twenty five|25 minutes|twenty-five minutes|twenty five minutes',why:'Twenty-five minutes describes the delay. Forty minutes was how long remained before the connection when he saw the notification.',evidence:'The new arrival time was only twenty-five minutes later than my original plan.',hint:'The story contains several numbers. This question asks about lateness at the destination, not time before a connection or remaining battery.'},
 {type:'sequence',prompt:'Put these events in the order you hear them.',answer:['He saw the cancellation notice.','He translated the bus announcement.','He followed passengers to the bus.','He messaged his friend.'],why:'The cancellation came first. Translation explained the bus; passengers then led him there. He sent his friend a message on the bus.',evidence:'I sent my friend a quick message and finally felt relieved.',hint:'Use the changing locations as anchors: on the train, at the station, then on the bus. The message to his friend comes after he checks the new route.'},
 {type:'choice',prompt:'What can we reasonably conclude from the story?',answer:'He now prepares for problems but stays flexible.',options:['He now prepares for problems but stays flexible.','He has stopped planning journeys.','He now always travels with a friend.'],why:'He carries a power bank but also trusts the first plan less. He does not say he has stopped planning or travelling alone.',evidence:'Since then, I always carry a small power bank, and I try not to trust the first plan too much.',hint:'Look for two changes in the last sentence: one practical preparation and one change in attitude. Choose a conclusion supported by both.'}
