function beep(ok,complete=false){if(!sound)return;feedbackAudio.pause();feedbackAudio.src='../course-a2-preview/sounds/'+(complete?'lesson.wav':ok?'success.mp3':'error.wav');feedbackAudio.volume=.6;feedbackAudio.play().catch(()=>announce('Sound could not play. Check your browser sound settings.'));}
let hintOpen=false;
const localDay=()=>new Date().toLocaleDateString('en-CA');
function streak(){const days=new Set(Object.values(state.answers).filter(x=>x.correct&&x.updatedAt).map(x=>new Date(x.updatedAt).toLocaleDateString('en-CA')));let d=new Date(),n=0;if(!days.has(d.toLocaleDateString('en-CA')))d.setDate(d.getDate()-1);while(days.has(d.toLocaleDateString('en-CA'))){n++;d.setDate(d.getDate()-1);}return n;}
function wordsToday(){return Object.entries(state.answers).filter(([id,a])=>id.startsWith('v')&&a.correct&&new Date(a.updatedAt).toLocaleDateString('en-CA')===localDay()).length;}
function hintText(q){return B.hints[q.originalId||q.id]||'Review the sentence and the grammar notes for this task.';}
function splitText(s,max=420){const chunks=[];const sentences=s.replace(/<br>/g,' · ').split(/(?<=[.!?])\s+(?=[A-Z*“])/);let chunk='';for(const sentence of sentences){if(sentence.length>max){if(chunk){chunks.push(chunk);chunk='';}let words=sentence.split(' '),part='';for(const w of words){if(part.length+w.length>max&&part){chunks.push(part);part='';}part+=(part?' ':'')+w;}if(part)chunks.push(part);}else if(chunk.length+sentence.length>max){chunks.push(chunk);chunk=sentence;}else chunk+=(chunk?' ':'')+sentence;}if(chunk)chunks.push(chunk);return chunks;}
function paginateTheory(text){const parts=[];let heading='Key idea',headers=null;for(const raw of text.replace(/\r/g,'').split('\n')){const line=raw.trim();if(!line)continue;if(/^#{1,4} /.test(line)){heading=line.replace(/^#+ /,'').replace(/\*/g,'');headers=null;continue;}if(line.startsWith('|')){const cells=line.slice(1,-1).split('|').map(x=>x.trim());if(cells.every(x=>/^[-: ]+$/.test(x)))continue;if(!headers){headers=cells;continue;}const row=cells.map((x,i)=>x?`**${headers[i].replace(/\*/g,'')}:** ${x}`:'').filter(Boolean).join('  ·  ');for(const chunk of splitText(row))parts.push({title:heading,text:chunk});continue;}headers=null;for(const chunk of splitText(line))parts.push({title:heading,text:chunk});}
const pages=[];for(const p of parts){const prev=pages[pages.length-1];if(prev&&prev.title===p.title&&prev.text.length+p.text.length<450)prev.text+='\n\n'+p.text;else pages.push({...p});}return pages;}
const theoryPages=new Map(B.lessons.map(x=>[x.n,state.savedTheoryPages[x.n]?.source===x.theory?state.savedTheoryPages[x.n].pages:paginateTheory(x.theory)]));
function currentTasks(){if(view==='review')return reviewDeck;if(view==='exam')return examQuestions();if(state.phase==='grammar')return l().tasks;if(state.phase==='listening')return l().listening;return [];}
function qNow(){return currentTasks()[view==='review'?reviewIndex:view==='exam'?step:state.phase==='listening'?step-1:step];}
function vocabQuestion(v){return {id:v.id,type:'choice',prompt:`What does “${v.word}” mean?`,answer:v.definition,options:[v.definition,...E.shuffle(l().vocab.filter(x=>x.id!==v.id).map(x=>x.definition),v.word.length).slice(0,2)],why:`${v.word}: ${v.definition}`};}
function getCurrentQuestion(){return state.phase==='vocabulary'&&view==='lesson'?vocabQuestion(l().vocab[step]):qNow();}
function examQuestions(){return E.shuffle(B.lessons.filter(x=>x.module===examModule).flatMap(x=>x.tasks),55+examModule).slice(0,12).map(q=>({...q,originalId:q.id,id:`exam${examModule}-${q.id}`}));}
function footer(left,right){return `<div class="flow-actions">${left}${right}</div>`;}
const btn=(text,action,cls='primary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
function frame(label,at,total,body,actions,extra=''){return `<div class="lesson-flow"><div class="flow-top">${btn('← Course map','map','quiet')}<span class="pill">${esc(label)}</span><div class="progress" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${Math.min(at,total)}"><span style="width:${Math.min(at/Math.max(1,total),1)*100}%"></span></div><span class="small">${at} / ${total}</span></div><section class="flow-card ${extra}"><div class="flow-content">${body}</div>${actions}</section></div>`;}
function phaseFooter(nextText='Continue'){return footer(btn(step?'Back':'Course map',step?'back':'map','quiet'),btn(nextText,'next'));}
function map(){const due=E.due(state,allQuestions).length,words=wordsToday(),xp=Object.values(state.answers).filter(a=>a.correct).length*10;return `<div class="dashboard"><section><section class="map-head"><span class="pill">B1 · 01</span><h1>B1 Intermediate</h1><p class="muted">My course · ${state.completed.length}/41</p><div class="stats"><div class="stat"><strong>${xp} XP</strong><small>Evo-English</small></div><div class="stat"><strong>🔥 ${streak()}</strong><small>Study streak</small></div><div class="stat"><strong>${state.completed.length}/41</strong><small>B1 Intermediate</small></div></div>${btn('Continue','resume')}<div class="daily-goal"><div><strong>Today’s goal</strong><p>Complete one lesson or recall five words.</p><small>Words today: ${Math.min(5,words)}/5</small></div>${btn('Review words','words')}</div>${!saveOK?'<p class="notice">Storage is unavailable. Export a backup before closing.</p>':''}</section><div class="journey">${B.modules.map((m,i)=>`<div class="module-label">MODULE ${i+1} · ${esc(m.title.toUpperCase())}</div>${B.lessons.filter(x=>x.module===i).map(x=>`<div class="node ${state.completed.includes(x.n)?'done':x.n===state.current?'current':''}"><div class="orb">${state.completed.includes(x.n)?'✓':x.n}</div><article class="node-card"><h2>${esc(x.title)}</h2><p>${esc(x.goal)}</p>${btn(state.completed.includes(x.n)?'Practise again':'Start lesson','lesson','primary',`data-n="${x.n}"`)}</article></div>`).join('')}<div class="checkpoint">${btn('Module checkpoint · 12 mixed tasks','exam','secondary',`data-n="${i}"`)}</div>`).join('')}</div></section><aside><section class="aside-card"><div class="goal-icon" aria-hidden="true">✦</div><h2>Today’s goal</h2><div class="welcome-illustration"><div class="avatar">A</div><div class="bubble">Hi!</div><div class="avatar warm">D</div></div><p class="muted">Complete one lesson or recall five words.</p></section><section class="aside-card"><span class="pill">A1 → C1</span><div class="levels">${['A1','A2','B1','B2','C1'].map(level=>`<span class="${level==='B1'?'active':''}">${level}</span>`).join('')}</div><p class="small">B1 · 41 lessons · Grammar, listening, vocabulary, writing and speaking.</p></section><section class="aside-card course-tools">${btn(`Review mistakes${due?` · ${due} due`:''}`,'review','secondary')}${btn('Audio library','library','secondary')}${btn('Export progress','export','quiet')}<p class="small">Progress and drafts are saved on this device.</p></section></aside></div>`;}
function choiceControls(q){const selected=view==='exam'?examDraft[q.id]:state.taskDrafts[q.id]??state.answers[q.id]?.answer;return `<div class="choices">${E.shuffle(q.options,q.id.split('').reduce((a,c)=>a+c.charCodeAt(0),0)).map((x,i)=>`<label class="option"><input type="radio" name="${q.id}" value="${esc(x)}" ${selected===x?'checked':''}><span class="option-num">${i+1}</span><span>${esc(x)}</span></label>`).join('')}</div>`;}
function controls(q){if(q.options)return choiceControls(q);if(q.type==='order'){const tokens=E.tokens(q),picked=arrangements[q.id]||[];return `<div class="assembled" aria-label="Your sentence">${picked.map(i=>btn(esc(tokens[i])+' ×','remove-token','token',`data-i="${i}"`)).join('')}</div><div class="token-bank">${tokens.map((w,i)=>btn(esc(w),'token','token',`data-i="${i}" ${picked.includes(i)?'disabled':''}`)).join('')}</div>`;}if(q.type==='sequence'){const rows=arrangements[q.id]||E.shuffle(q.answer,31+q.id.length);arrangements[q.id]=rows;return rows.map((s,i)=>`<div class="sequence-row"><span>${i+1}. ${esc(s)}</span>${btn('↑','move','secondary',`data-i="${i}" data-dir="-1" aria-label="Move event ${i+1} up" ${i===0?'disabled':''}`)}${btn('↓','move','secondary',`data-i="${i}" data-dir="1" aria-label="Move event ${i+1} down" ${i===rows.length-1?'disabled':''}`)}</div>`).join('');}return `<label class="small" for="answer">${q.type==='gap'?'Write only the missing word(s).':'Write the complete sentence using the wording in the task.'}</label><input id="answer" class="answer-input" autocomplete="off" spellcheck="false" value="${esc(view==='exam'?examDraft[q.id]||'':state.taskDrafts[q.id]??state.answers[q.id]?.answer??'')}" aria-label="Your answer">`;}
function inputAnswer(q){if(q.options)return document.querySelector(`input[name="${q.id}"]:checked`)?.value||'';if(q.type==='order'){const tokens=E.tokens(q);return (arrangements[q.id]||[]).map(i=>tokens[i]).join(' ');}if(q.type==='sequence')return arrangements[q.id]||[];return document.getElementById('answer')?.value||'';}
function syncReady(){const check=main.querySelector('[data-action="check"], [data-action="exam-next"]');if(check){const q=getCurrentQuestion();if(q){const answer=inputAnswer(q);check.disabled=!answer||Array.isArray(answer)&&!answer.length||q.type==='order'&&(arrangements[q.id]||[]).length!==E.tokens(q).length;}}const cachedButton=main.querySelector('[data-action="show-ai"]');if(cachedButton&&!validReview(state.phase)){cachedButton.dataset.action='analyse';cachedButton.textContent='Analyse with AI';cachedButton.onclick=()=>act('analyse',{});}const analyse=main.querySelector('[data-action="analyse"]');if(analyse)analyse.disabled=!!aiBusy||count(answerStore(state.phase)[l().n]||'')<(state.phase==='writing'?80:20);const next=main.querySelector('[data-action="next"]');if(next&&view==='lesson'&&['writing','speaking'].includes(state.phase))next.disabled=!!aiBusy||!!recorder||(step===2&&!validReview(state.phase));}
function audio(src,title){return `<audio class="lesson-audio" controls preload="none" src="${esc(src)}" aria-label="${esc(title)}"></audio>`;}
function question(q,label,n,total,listen=false){if(!q)return resultScreen();if(hintOpen)return frame(label,n,total,`<span class="pill">HINT</span><h1>Think it through.</h1><div class="hint">${esc(hintText(q))}</div><p class="small">Return to the question and try the rule yourself.</p>`,footer(btn('Back to question','hint','quiet'),btn('Try it','hint')));if(feedback?.pages){const p=feedback.pages[feedback.page];return frame(label,n,total,`<span class="pill">${feedback.correct?'✓ CORRECT':'↻ REVIEW THIS POINT'}</span><h1>${esc(p.title)}</h1><div class="feedback-panel ${feedback.correct?'':'bad'}"><p>${esc(p.text)}</p></div><p class="small">Explanation · ${feedback.page+1}/${feedback.pages.length}</p>`,footer(btn('Try again','retry','quiet'),btn('Continue','next')));}if(feedback){const ok=feedback.correct;return frame(label,n,total,`<span class="pill">${ok?'✓ CORRECT':'↻ REVIEW THIS POINT'}</span><h1 class="question-text">${esc(q.prompt)}</h1><div class="feedback-panel ${ok?'':'bad'}"><h2>${ok?'✓ Correct':'↻ Try again'}</h2>${true?`<div class="model">${esc(q.answer instanceof Array?q.answer.join(' → '):q.answer.split('|')[0])}</div>`:''}<p>${esc(q.why||'Check the precise detail in the recording.')}</p></div>${q.evidence?`<blockquote class="evidence">“${esc(q.evidence)}”</blockquote>`:''}<p class="small">First attempt: ${state.answers[q.id]?.firstCorrect?'correct':'needs review'}. Incorrect points enter your review queue.</p>`,footer(btn('Try again','retry','quiet'),btn('Continue','next')));}
const kind=q.type==='rewrite'?'SENTENCE TRANSFORMATION':q.type==='edit'?'ERROR CORRECTION':q.type==='order'?'SENTENCE BUILDING':q.type==='sequence'?'SEQUENCE':q.type==='gap'?'GAP FILL':q.type==='truth'?'TRUE / FALSE':'CHOOSE AN ANSWER';
return frame(label,n,total,`<span class="stage-tag">${kind}</span><h1 class="question-text">${esc(q.type==='sequence'?'Put the events in the order you hear them.':q.prompt)}</h1>${listen?audio(l().audio,'Replay lesson audio'):''}${controls(q)}`,footer(btn(view==='exam'?'Back':'Hint',view==='exam'?'back':'hint','quiet'),btn(view==='exam'?(step===total-1?'Submit checkpoint':'Next question'):'Check',view==='exam'?'exam-next':'check')),'question-card');}
function theory(){const pages=theoryPages.get(l().n);step=Math.min(step,pages.length-1);const p=pages[step];return frame('GRAMMAR',step+1,pages.length,`<span class="pill">B1 · ${l().n}/41</span><h1>${esc(p.title)}</h1><div class="theory-text">${p.text.split('\n\n').map(x=>`<p>${inline(x.replace(/^- /,'• '))}</p>`).join('')}</div>`,phaseFooter(step===pages.length-1?'Start practice':'Continue'));}
function listening(){if(step===0)return frame('LISTENING',1,l().listening.length+1,`<span class="pill">🎧 LISTENING</span><h1>${esc(l().audioTitle)}</h1><p class="muted">Listen for the main idea first. Then answer one question at a time.</p>${audio(l().audio,l().audioTitle)}<div class="speed-control"><label for="speed">Speed</label><select id="speed"><option value="0.8">0.8×</option><option value="1">1×</option><option value="1.15">1.15×</option></select>${btn('Read transcript','transcript','quiet')}</div><p class="small">${esc(l().mappingNote)}</p>`,phaseFooter('Start questions'));return question(qNow(),'LISTENING TASKS',step,l().listening.length,true);}
let transcriptNumber=1,transcriptReturn='lesson',transcriptIndex=0;
function transcriptBlock(source){return `<div class="transcript-text transcript-scroll" tabindex="0" role="region" aria-label="Full transcript" lang="en">${source.transcript.map(p=>`<p>${esc(p)}</p>`).join('')}</div>`;}
function transcriptScreen(){const source=B.audioLibrary.find(x=>x.n===transcriptNumber);return frame('TRANSCRIPT',1,1,`<span class="pill">${esc(source.speaker)}</span><h1>${esc(source.title)}</h1>${audio(source.audio,source.title)}${transcriptBlock(source)}`,footer(btn('Back','transcript-exit','quiet'),btn('Back to listening','transcript-exit')),'transcript-card');}
function vocab(){const v=l().vocab[step];if(!v)return resultScreen();return question(vocabQuestion(v),'VOCABULARY',step+1,l().vocab.length);}
state.aiReviews ||= {};state.speechAnswers ||= {};
let aiBusy=null,aiError='',aiTab='summary',recordBlob=null,recordTimer=null;
const answerStore=kind=>kind==='writing'?state.drafts:state.speechAnswers;
const reviewKey=(kind,n=state.current)=>`${kind}-${n}`;
function validReview(kind,n=state.current){const r=state.aiReviews[reviewKey(kind,n)];return r&&r.text===(answerStore(kind)[n]||'').trim()?r:null;}
function reviewBody(r){const f=r.feedback,rating={good:'Good work',almost:'Almost there',needs_work:'Keep practising'};if(aiTab==='corrections')return f.corrections.length?f.corrections.map(c=>`<article class="ai-correction"><div class="small">Your words</div><p>${esc(c.original)}</p><div class="small">Suggested correction</div><p><strong>${esc(c.correction)}</strong></p><p class="small">${esc(c.explanation)}</p></article>`).join(''):'<p>No important corrections were suggested.</p>';if(aiTab==='version')return `<p class="small">AI suggestion — compare it with your answer.</p><div class="ai-version">${esc(f.improved_version)}</div>`;return `<h2>${rating[f.overall_rating]}</h2><p>${esc(f.positive)}</p>${['task_completion','grammar','vocabulary','clarity'].map(key=>`<div class="ai-rubric"><strong>${({task_completion:'Task',grammar:'Grammar',vocabulary:'Vocabulary',clarity:'Clarity'})[key]}</strong><span>${esc(f[key].feedback)}</span></div>`).join('')}<div class="ai-next"><strong>Try next</strong><p>${esc(f.next_step)}</p></div>`;}
function production(kind){const isWrite=kind==='writing',r=validReview(kind);if(step>2)step=r?2:1;if(step===2&&!r)step=1;
if(step===0)return frame(names[kind],1,3,`<span class="pill">${isWrite?'✍ WRITING':'🎙 SPEAKING'}</span><h1>${isWrite?'Your writing task':'Your speaking turn'}</h1><div class="production-brief">${esc(isWrite?l().writing:l().speaking)}</div><p class="small">${isWrite?'Write 80–120 words, then get an AI review.':'Speak for 60–90 seconds. Record and transcribe, or type what you said.'}</p>${isWrite?'':`<div class="record-controls">${btn(recorder?'Stop recording':'Record answer','record','secondary',aiBusy?'disabled':'')}${recordBlob&&recordLesson===l().n?btn(aiBusy?'Transcribing…':'Transcribe recording','transcribe','primary',aiBusy?'disabled':''):''}</div><p class="record-status" id="record-status">${recordBlob&&recordLesson===l().n?'Recording ready. Transcribe sends it to AI.':'The recording stays here until you choose Transcribe.'}</p>${recordUrl&&recordLesson===l().n?audio(recordUrl,'Your recording'):''}<p class="small">AI reviews the transcript’s language, not pronunciation.</p>`}${aiError?`<p class="ai-error" role="alert">${esc(aiError)}</p>`:''}`,phaseFooter(isWrite?'Write your answer':'Your spoken answer'),'production-card');
if(step===1){const text=answerStore(kind)[l().n]||'';return frame(names[kind],2,3,`<span class="pill">${isWrite?'YOUR TEXT':'YOUR SPOKEN ANSWER'}</span><h1>${isWrite?'Write in your own words.':'Check your transcript.'}</h1><details class="production-task"><summary>Task</summary><p>${esc(isWrite?l().writing:l().speaking)}</p></details><label class="sr-only" for="draft">${isWrite?'Your writing answer':'Your spoken answer transcript'}</label><textarea class="draft-input" id="draft" maxlength="6000" ${aiBusy?'readonly':''} placeholder="${isWrite?'Write your answer in English…':'Paste, transcribe or type what you said…'}">${esc(text)}</textarea><p class="word-count" id="word-count">${count(text)} words · saved on this device</p><p class="small">${isWrite?'Analyse sends this text to AI for feedback.':'Correct recognition errors before analysing. AI checks the words, not pronunciation.'}</p>${aiError?`<p class="ai-error" role="alert">${esc(aiError)}</p>`:''}`,footer(btn('Back','back','quiet'),btn(aiBusy?'Checking…':r?'View AI review':'Analyse with AI',r?'show-ai':'analyse','primary',aiBusy?'disabled':'')),'production-card');}
return frame(names[kind],3,3,`<span class="pill">AI REVIEW</span><h1>Improve your answer.</h1><div class="ai-tabs" role="group" aria-label="AI feedback section">${[['summary','Summary'],['corrections','Corrections'],['version','Improved text']].map(([id,label])=>btn(label,'ai-tab',aiTab===id?'active':'',`data-tab="${id}" aria-pressed="${aiTab===id}"`)).join('')}</div><section class="ai-review-scroll" tabindex="0" aria-label="AI feedback">${reviewBody(r)}</section>${!isWrite?'<p class="small">Feedback is based on your transcript.</p>':''}`,footer(btn('Edit answer','edit-ai','quiet'),btn(isWrite?'Continue to speaking':'Finish lesson','next')),'ai-review-card');}
async function analyseAnswer(){if(aiBusy)return;if(validReview(state.phase)){step=2;aiTab='summary';render();return;}const kind=state.phase,n=l().n,text=(answerStore(kind)[n]||'').trim();if(count(text)<(kind==='writing'?80:20)){announce(kind==='writing'?'Write at least 80 words.':'Add at least 20 words from your spoken answer.');return;}const lesson=l();aiBusy=reviewKey(kind,n);aiError='';render(false);try{const result=await B1_AI.review(lesson,kind,text);if((answerStore(kind)[n]||'').trim()===text){state.aiReviews[reviewKey(kind,n)]={text,feedback:result,at:Date.now()};if(view==='lesson'&&state.current===n&&state.phase===kind){step=2;aiTab='summary';}}}catch(e){if(state.current===n&&state.phase===kind)aiError=e.message||'AI feedback is unavailable. Please try again.';}finally{aiBusy=null;save();if(view==='lesson'&&state.current===n&&state.phase===kind)render(false);}}
async function transcribeAnswer(){if(aiBusy||!recordBlob||recordLesson!==l().n)return;const n=l().n,blob=recordBlob;aiBusy='transcribe';aiError='';render(false);try{const text=await B1_AI.transcribe(blob);state.speechAnswers[n]=text;if(view==='lesson'&&state.current===n&&state.phase==='speaking')step=1;}catch(e){if(state.current===n)aiError=e.message||'Transcription failed.';}finally{aiBusy=null;save();if(view==='lesson'&&state.current===n&&state.phase==='speaking')render(false);}}

function missing(){const x=l(),m=[];if(!x.tasks.every(q=>state.answers[q.id]?.correct))m.push('Grammar practice');if(!x.listening.every(q=>state.answers[q.id]?.correct))m.push('Listening tasks');if(!x.vocab.every(v=>state.answers[v.id]?.correct))m.push('Vocabulary');if(!validReview('writing'))m.push('Writing AI review');if(!validReview('speaking'))m.push('Speaking AI review');return m;}
function resultScreen(){const m=missing();return frame('LESSON SUMMARY',1,1,`<span class="result-symbol">${m.length?'↻':'★'}</span><h1>${m.length?'Keep practising.':'Lesson complete!'}</h1><p class="muted">${esc(l().title)}</p>${m.length?`<div class="theory-text">${m.slice(0,1).map(x=>`<p>• ${esc(x)}</p>`).join('')}</div><p class="small">This step still needs attention. Revisit it, then continue.</p><div class="record-controls">${phases.filter(p=>p===({ 'Grammar practice':'grammar','Listening tasks':'listening','Vocabulary':'vocabulary','Writing AI review':'writing','Speaking AI review':'speaking' }[m[0]]||(m[0].startsWith('Writing')?'writing':'speaking'))).map(p=>btn(names[p],'stage','secondary',`data-phase="${p}"`)).join('')}</div>`:`<p class="muted">You practised grammar, listening, vocabulary, writing and speaking.</p><div class="result-stats"><div class="stat"><strong>${state.completed.length}/41</strong><small>Lessons complete</small></div><div class="stat"><strong>${l().tasks.filter(q=>state.answers[q.id]?.firstCorrect).length}/8</strong><small>Grammar first attempts</small></div></div>`}`,footer(btn('Course map','map','quiet'),m.length?btn('Review mistakes','review'):btn(state.current<41?'Next lesson':'Course map',state.current<41?'next-lesson':'map')));}
function reviewScreen(){if(reviewIndex>=reviewDeck.length)return frame('REVIEW',reviewDeck.length,Math.max(1,reviewDeck.length),`<span class="result-symbol">✓</span><h1>Review session complete.</h1><p class="muted">Correctly recalled points return after 1, 3, 7 and 14 days. Difficult points remain due.</p>`,footer(btn('Course map','map','quiet'),btn('Continue course','resume')));return question(reviewDeck[reviewIndex],'REVIEW',reviewIndex+1,reviewDeck.length);}
let libraryIndex=0;
