function validate(data){const f=data?.feedback;const ratings=['good','almost','needs_work'];if(!data?.ok||!f||!ratings.includes(f.overall_rating))throw Error('AI returned an incomplete review. Please try again.');for(const key of ['task_completion','grammar','vocabulary','clarity'])if(!ratings.includes(f[key]?.rating)||typeof f[key]?.feedback!=='string')throw Error('AI returned an incomplete review. Please try again.');for(const key of ['positive','next_step','improved_version'])if(typeof f[key]!=='string')throw Error('AI returned an incomplete review. Please try again.');if(!Array.isArray(f.corrections)||f.corrections.length>20||f.corrections.some(c=>['original','correction','explanation'].some(k=>typeof c[k]!=='string')))throw Error('AI returned invalid corrections. Please try again.');return f;}
